import { describe, expect, it } from 'vitest'

import { Harness } from './harness.js'

describe('harness', () => {
  it('renders the active row differently from the inactive one', () => {
    const rows = new Harness(['alpha', 'alpha']).renderRows()
    expect(rows[0]).not.toBe(rows[1])
  })
})

