export class Harness {
  private readonly items: string[]

  constructor(items: string[]) {
    this.items = items
  }

  renderRows(): string[] {
    const selection = new Selection(ItemId.named('first'))
    return this.items.map((item, index) =>
      selection.covers(index) ? `> ${item}` : item,
    )
  }
}
